    <form class="topbar-search" method="GET" action="/crm/search.php">
      <?= crm_icon('search') ?>
      <input type="text" name="q" placeholder="Search customers, mobile, bookings…" value="<?= htmlspecialchars($_GET['q'] ?? '') ?>">
