          <div class="user-avatar"><?= strtoupper(substr($user['name'] ?? 'A', 0, 1)) ?></div>
        <?php endif; ?>
        <div class="user-info">
          <span class="user-name"><?= htmlspecialchars($user['name'] ?? 'Admin') ?></span>
          <span class="user-role"><?= htmlspecialchars(ucwords(str_replace('_',' ', $user['role'] ?? 'admin'))) ?></span>
        </div>
      </div>
